  // LPCG access control
  struct Lpcg45AuthenFields {
    enum class eTZ_USER : std::uint32_t {
      // LPCG cannot be changed in user mode.
      eTZ_USER_0 = 0,
      // LPCG can be changed in user mode.
      eTZ_USER_1 = 1,
    };

    enum class eTZ_NS : std::uint32_t {
      // Cannot be changed in Non-secure mode.
      eTZ_NS_0 = 0,
      // Can be changed in Non-secure mode.
      eTZ_NS_1 = 1,
    };

    enum class eLOCK_TZ : std::uint32_t {
      // Trustzone setting is not locked.
      eLOCK_TZ_0 = 0,
      // Trustzone setting is locked.
      eLOCK_TZ_1 = 1,
    };

    enum class eLOCK_LIST : std::uint32_t {
      // Whitelist is not locked.
      eLOCK_LIST_0 = 0,
      // Whitelist is locked.
      eLOCK_LIST_1 = 1,
    };

    enum class eDOMAIN_MODE : std::uint32_t {
      // Clock does not work in Domain Mode
      eDOMAIN_MODE_0 = 0,
      // Clock works in Domain Mode
      eDOMAIN_MODE_1 = 1,
    };

    enum class eSETPOINT_MODE : std::uint32_t {
      // LPCG is not functioning in Setpoint controlled Mode
      eDISABLE = 0,
      // LPCG is functioning in Setpoint controlled Mode
      eENABLE = 1,
    };

    enum class eCPULPM : std::uint32_t {
      // LPCG is not functioning in Low power Mode
      eDISABLE = 0,
      // LPCG is functioning in Low Power Mode
      eENABLE = 1,
    };

    enum class eLOCK_MODE : std::uint32_t {
      // MODE is not locked.
      eLOCK_MODE_0 = 0,
      // MODE is locked.
      eLOCK_MODE_1 = 1,
    };

    // User access
    using TZ_USER = ftl::mmio::Field<1, 0, eTZ_USER, ftl::mmio::RW, ftl::mmio::Normal>;
    // Non-secure access
    using TZ_NS = ftl::mmio::Field<1, 1, eTZ_NS, ftl::mmio::RW, ftl::mmio::Normal>;
    // lock truszone setting
    using LOCK_TZ = ftl::mmio::Field<1, 4, eLOCK_TZ, ftl::mmio::RW, ftl::mmio::Normal>;
    // Whitelist
    using WHITE_LIST = ftl::mmio::Field<4, 8, std::uint8_t, ftl::mmio::RW, ftl::mmio::Normal>;
    // Lock Whitelist
    using LOCK_LIST = ftl::mmio::Field<1, 12, eLOCK_LIST, ftl::mmio::RW, ftl::mmio::Normal>;
    // Low power and access control by domain
    using DOMAIN_MODE = ftl::mmio::Field<1, 16, eDOMAIN_MODE, ftl::mmio::RW, ftl::mmio::Normal>;
    // Low power and access control by Setpoint
    using SETPOINT_MODE = ftl::mmio::Field<1, 17, eSETPOINT_MODE, ftl::mmio::RW, ftl::mmio::Normal>;
    // CPU Low Power Mode
    using CPULPM = ftl::mmio::Field<1, 18, eCPULPM, ftl::mmio::RW, ftl::mmio::Normal>;
    // Lock low power and access mode
    using LOCK_MODE = ftl::mmio::Field<1, 20, eLOCK_MODE, ftl::mmio::RW, ftl::mmio::Normal>;
  };  // struct Lpcg45AuthenFields

