  struct Lpcg50DomainFields {
    enum class eLEVEL : std::uint32_t {
      // This clock source is not needed in any mode, and can be turned off
      eNO = 0,
      // This clock source is needed in RUN mode, but not needed in WAIT, STOP mode
      eR = 1,
      // This clock source is needed in RUN and WAIT mode, but not needed in STOP mode
      eRW = 2,
      // This clock source is needed in RUN, WAIT and STOP mode
      eRWS = 3,
      // This clock source is always on in any mode (including SUSPEND)
      eALL = 4,
    };

    enum class eLEVEL0 : std::uint32_t {
      // This clock source is not needed in any mode, and can be turned off
      eNO = 0,
      // This clock source is needed in RUN mode, but not needed in WAIT, STOP mode
      eR = 1,
      // This clock source is needed in RUN and WAIT mode, but not needed in STOP mode
      eRW = 2,
      // This clock source is needed in RUN, WAIT and STOP mode
      eRWS = 3,
      // This clock source is always on in any mode (including SUSPEND)
      eALL = 4,
    };

    enum class eLEVEL1 : std::uint32_t {
      // This clock source is not needed in any mode, and can be turned off
      eNO = 0,
      // This clock source is needed in RUN mode, but not needed in WAIT, STOP mode
      eR = 1,
      // This clock source is needed in RUN and WAIT mode, but not needed in STOP mode
      eRW = 2,
      // This clock source is needed in RUN, WAIT and STOP mode
      eRWS = 3,
      // This clock source is always on in any mode (including SUSPEND)
      eALL = 4,
    };

    enum class eLEVEL2 : std::uint32_t {
      // This clock source is not needed in any mode, and can be turned off
      eNO = 0,
      // This clock source is needed in RUN mode, but not needed in WAIT, STOP mode
      eR = 1,
      // This clock source is needed in RUN and WAIT mode, but not needed in STOP mode
      eRW = 2,
      // This clock source is needed in RUN, WAIT and STOP mode
      eRWS = 3,
      // This clock source is always on in any mode (including SUSPEND)
      eALL = 4,
    };

    enum class eLEVEL3 : std::uint32_t {
      // This clock source is not needed in any mode, and can be turned off
      eNO = 0,
      // This clock source is needed in RUN mode, but not needed in WAIT, STOP mode
      eR = 1,
      // This clock source is needed in RUN and WAIT mode, but not needed in STOP mode
      eRW = 2,
      // This clock source is needed in RUN, WAIT and STOP mode
      eRWS = 3,
      // This clock source is always on in any mode (including SUSPEND)
      eALL = 4,
    };

    // Current dependence level
    using LEVEL = ftl::mmio::Field<3, 0, eLEVEL, ftl::mmio::RW, ftl::mmio::Normal>;
    // Depend level
    using LEVEL0 = ftl::mmio::Field<3, 16, eLEVEL0, ftl::mmio::RW, ftl::mmio::Normal>;
    // Depend level
    using LEVEL1 = ftl::mmio::Field<3, 20, eLEVEL1, ftl::mmio::RW, ftl::mmio::Normal>;
    // Depend level
    using LEVEL2 = ftl::mmio::Field<3, 24, eLEVEL2, ftl::mmio::RW, ftl::mmio::Normal>;
    // Depend level
    using LEVEL3 = ftl::mmio::Field<3, 28, eLEVEL3, ftl::mmio::RW, ftl::mmio::Normal>;
  };  // struct Lpcg50DomainFields

