  // LPCG domain control
  struct Lpcg94DomainFields {
    enum class eLEVEL : std::uint32_t {
      // This clock source is not needed in any mode, and can be turned off
      eNO = 0,
      // This clock source is needed in RUN mode, but not needed in WAIT, STOP mode
      eR = 1,
      // This clock source is needed in RUN and WAIT mode, but not needed in STOP mode
      eRW = 2,
      // This clock source is needed in RUN, WAIT and STOP mode
      eRWS = 3,
      // This clock source is always on in any mode (including SUSPEND)
      eALL = 4,
    };

    enum class eLEVEL0 : std::uint32_t {
      // This clock source is not needed in any mode, and can be turned off
      eNO = 0,
      // This clock source is needed in RUN mode, but not needed in WAIT, STOP mode
      eR = 1,
      // This clock source is needed in RUN and WAIT mode, but not needed in STOP mode
      eRW = 2,
      // This clock source is needed in RUN, WAIT and STOP mode
      eRWS = 3,
      // This clock source is always on in any mode (including SUSPEND)
      eALL = 4,
    };

    enum class eLEVEL1 : std::uint32_t {
      // This clock source is not needed in any mode, and can be turned off
      eNO = 0,
      // This clock source is needed in RUN mode, but not needed in WAIT, STOP mode
      eR = 1,
      // This clock source is needed in RUN and WAIT mode, but not needed in STOP mode
      eRW = 2,
      // This clock source is needed in RUN, WAIT and STOP mode
      eRWS = 3,
      // This clock source is always on in any mode (including SUSPEND)
      eALL = 4,
    };

    enum class eLEVEL2 : std::uint32_t {
      // This clock source is not needed in any mode, and can be turned off
      eNO = 0,
      // This clock source is needed in RUN mode, but not needed in WAIT, STOP mode
      eR = 1,
      // This clock source is needed in RUN and WAIT mode, but not needed in STOP mode
      eRW = 2,
      // This clock source is needed in RUN, WAIT and STOP mode
      eRWS = 3,
      // This clock source is always on in any mode (including SUSPEND)
      eALL = 4,
    };

    enum class eLEVEL3 : std::uint32_t {
      // This clock source is not needed in any mode, and can be turned off
      eNO = 0,
      // This clock source is needed in RUN mode, but not needed in WAIT, STOP mode
      eR = 1,
      // This clock source is needed in RUN and WAIT mode, but not needed in STOP mode
      eRW = 2,
      // This clock source is needed in RUN, WAIT and STOP mode
      eRWS = 3,
      // This clock source is always on in any mode (including SUSPEND)
      eALL = 4,
    };

    // Current dependence level
    using LEVEL = ftl::mmio::Field<3, 0, eLEVEL, ftl::mmio::RW, ftl::mmio::Normal>;
    // Depend level
    using LEVEL0 = ftl::mmio::Field<3, 16, eLEVEL0, ftl::mmio::RW, ftl::mmio::Normal>;
    // Depend level
    using LEVEL1 = ftl::mmio::Field<3, 20, eLEVEL1, ftl::mmio::RW, ftl::mmio::Normal>;
    // Depend level
    using LEVEL2 = ftl::mmio::Field<3, 24, eLEVEL2, ftl::mmio::RW, ftl::mmio::Normal>;
    // Depend level
    using LEVEL3 = ftl::mmio::Field<3, 28, eLEVEL3, ftl::mmio::RW, ftl::mmio::Normal>;
  };  // struct Lpcg94DomainFields

  struct LPCG94_DOMAIN : ftl::mmio::Register<
      0x40CC6BC4u,
      std::uint32_t,
      0x00010001u,
      ftl::mmio::RW,
      Lpcg94DomainFields::LEVEL,
      ftl::mmio::Reserved<13, 3>,
      Lpcg94DomainFields::LEVEL0,
      ftl::mmio::Reserved<1, 19>,
      Lpcg94DomainFields::LEVEL1,
      ftl::mmio::Reserved<1, 23>,
      Lpcg94DomainFields::LEVEL2,
      ftl::mmio::Reserved<1, 27>,
      Lpcg94DomainFields::LEVEL3,
      ftl::mmio::Reserved<1, 31>> {
    using eLEVEL = Lpcg94DomainFields::eLEVEL;
    using eLEVEL0 = Lpcg94DomainFields::eLEVEL0;
    using eLEVEL1 = Lpcg94DomainFields::eLEVEL1;
    using eLEVEL2 = Lpcg94DomainFields::eLEVEL2;
    using eLEVEL3 = Lpcg94DomainFields::eLEVEL3;
    using LEVEL = Lpcg94DomainFields::LEVEL;
    using LEVEL0 = Lpcg94DomainFields::LEVEL0;
    using LEVEL1 = Lpcg94DomainFields::LEVEL1;
    using LEVEL2 = Lpcg94DomainFields::LEVEL2;
    using LEVEL3 = Lpcg94DomainFields::LEVEL3;
  };

  // LPCG working status
  struct Lpcg94Status0Fields {
    enum class eON : std::uint32_t {
      // LPCG is OFF.
      eON_0 = 0,
      // LPCG is ON.
      eON_1 = 1,
    };

    enum class eACTIVE_DOMAIN : std::uint32_t {
      // Clock not owned by any domain
      eNO = 0,
      // Clock owned by Domain0
      eZERO = 1,
      // Clock owned by Domain1
      eTWO = 2,
      // Clock owned by Domain0 and Domain1
      eTHREE = 3,
      // Clock owned by Domain2
      eFOUR = 4,
      // Clock owned by Domain0 and Domain2
      eFIVE = 5,
      // Clock owned by Domain1 and Domain2
      eSIX = 6,
      // Clock owned by Domain0, Domain1 and Domain 2
      eSEVEN = 7,
      // Clock owned by Domain3
      eEIGHT = 8,
      // Clock owned by Domain0 and Domain3
      eNINE = 9,
      // Clock owned by Domain1 and Domain3
      eTEN = 10,
      // Clock owned by Domain2 and Domain3
      eELV = 11,
      // Clock owned by Domain0, Domain 1, and Domain3
      eTW = 12,
      // Clock owned by Domain0, Domain 2, and Domain3
      eTH = 13,
      // Clock owned by Domain1, Domain 2, and Domain3
      eFR = 14,
      // Clock owned by all domains
      eall = 15,
    };

    enum class eDOMAIN_ENABLE : std::uint32_t {
      // No domain request
      eNO = 0,
      // Request from Domain0
      eZERO = 1,
      // Request from Domain1
      eTWO = 2,
      // Request from Domain0 and Domain1
      eTHREE = 3,
      // Request from Domain2
      eFOUR = 4,
      // Request from Domain0 and Domain2
      eFIVE = 5,
      // Request from Domain1 and Domain2
      eSIX = 6,
      // Request from Domain0, Domain1 and Domain 2
      eSEVEN = 7,
      // Request from Domain3
      eEIGHT = 8,
      // Request from Domain0 and Domain3
      eNINE = 9,
      // Request from Domain1 and Domain3
      eTEN = 10,
      // Request from Domain2 and Domain3
      eELV = 11,
      // Request from Domain0, Domain 1, and Domain3
      eTW = 12,
      // Request from Domain0, Domain 2, and Domain3
      eTH = 13,
      // Request from Domain1, Domain 2, and Domain3
      eFR = 14,
      // Request from all domains
      eall = 15,
    };

    // LPCG current state
    using ON = ftl::mmio::Field<1, 0, eON, ftl::mmio::RO, ftl::mmio::Normal>;
    // Domains that own this clock gate
    using ACTIVE_DOMAIN = ftl::mmio::Field<4, 8, eACTIVE_DOMAIN, ftl::mmio::RO, ftl::mmio::Normal>;
    // Enable status from each domain
    using DOMAIN_ENABLE = ftl::mmio::Field<4, 12, eDOMAIN_ENABLE, ftl::mmio::RO, ftl::mmio::Normal>;
  };  // struct Lpcg94Status0Fields

  struct LPCG94_STATUS0 : ftl::mmio::Register<
      0x40CC6BD0u,
      std::uint32_t,
      0x00000000u,
      ftl::mmio::RO,
      Lpcg94Status0Fields::ON,
      ftl::mmio::Reserved<7, 1>,
      Lpcg94Status0Fields::ACTIVE_DOMAIN,
      Lpcg94Status0Fields::DOMAIN_ENABLE,
      ftl::mmio::Reserved<16, 16>> {
    using eON = Lpcg94Status0Fields::eON;
    using eACTIVE_DOMAIN = Lpcg94Status0Fields::eACTIVE_DOMAIN;
    using eDOMAIN_ENABLE = Lpcg94Status0Fields::eDOMAIN_ENABLE;
    using ON = Lpcg94Status0Fields::ON;
    using ACTIVE_DOMAIN = Lpcg94Status0Fields::ACTIVE_DOMAIN;
    using DOMAIN_ENABLE = Lpcg94Status0Fields::DOMAIN_ENABLE;
  };

  // LPCG low power status
  struct Lpcg94Status1Fields {
    enum class eCPU0_MODE : std::uint32_t {
      // Run
      eRUN = 0,
      // Wait
      eWAIT = 1,
      // Stop
      eSTOP = 2,
      // Suspend
      eSUSPEND = 3,
    };

    enum class eCPU0_MODE_REQUEST : std::uint32_t {
      // No request
      eDIS = 0,
      // Request from domain to enter Low Power Mode
      eENABLE = 1,
    };

    enum class eCPU0_MODE_DONE : std::uint32_t {
      // Clock is not gated
      eDIS = 0,
      // Clock is gated-off
      eENABLE = 1,
    };

    enum class eCPU1_MODE : std::uint32_t {
      // Run
      eRUN = 0,
      // Wait
      eWAIT = 1,
      // Stop
      eSTOP = 2,
      // Suspend
      eSUSPEND = 3,
    };

    enum class eCPU1_MODE_REQUEST : std::uint32_t {
      // No request
      eDIS = 0,
      // Request from domain to enter Low Power Mode
      eENABLE = 1,
    };

    enum class eCPU1_MODE_DONE : std::uint32_t {
      // Clock is not gated
      eDIS = 0,
      // Clock is gated-off
      eENABLE = 1,
    };

    enum class eCPU2_MODE : std::uint32_t {
      // Run
      eRUN = 0,
      // Wait
      eWAIT = 1,
      // Stop
      eSTOP = 2,
      // Suspend
      eSUSPEND = 3,
    };

    enum class eCPU2_MODE_REQUEST : std::uint32_t {
      // No request
      eDIS = 0,
      // Request from domain to enter Low Power Mode
      eENABLE = 1,
    };

    enum class eCPU2_MODE_DONE : std::uint32_t {
      // Clock is not gated
      eDIS = 0,
      // Clock is gated-off
      eENABLE = 1,
    };

    enum class eCPU3_MODE : std::uint32_t {
      // Run
      eRUN = 0,
      // Wait
      eWAIT = 1,
      // Stop
      eSTOP = 2,
      // Suspend
      eSUSPEND = 3,
    };

    enum class eCPU3_MODE_REQUEST : std::uint32_t {
      // No request
      eDIS = 0,
      // Request from domain to enter Low Power Mode
      eENABLE = 1,
    };

    enum class eCPU3_MODE_DONE : std::uint32_t {
      // Clock is not gated
      eDIS = 0,
      // Clock is gated-off
      eENABLE = 1,
    };

    enum class eSETPOINT_OFF_REQUEST : std::uint32_t {
      // No request
      eDIS = 0,
      // Clock gate requested to be turned off
      eENABLE = 1,
    };

    enum class eSETPOINT_OFF_DONE : std::uint32_t {
      // Clock gate is not turned off
      eDIS = 0,
      // Clock gate is turned off
      eENABLE = 1,
    };

    enum class eSETPOINT_ON_REQUEST : std::uint32_t {
      // No request
      eDIS = 0,
      // Clock gate requested to be turned on
      eENABLE = 1,
    };

    enum class eSETPOINT_ON_DONE : std::uint32_t {
      // Clock gate is not turned on
      eDIS = 0,
      // Clock gate is turned on
      eENABLE = 1,
    };

    // Domain0 Low Power Mode
    using CPU0_MODE = ftl::mmio::Field<2, 0, eCPU0_MODE, ftl::mmio::RO, ftl::mmio::Normal>;
    // Domain0 request enter Low Power Mode
    using CPU0_MODE_REQUEST = ftl::mmio::Field<1, 2, eCPU0_MODE_REQUEST, ftl::mmio::RO, ftl::mmio::Normal>;
    // Domain0 Low Power Mode task done
    using CPU0_MODE_DONE = ftl::mmio::Field<1, 3, eCPU0_MODE_DONE, ftl::mmio::RO, ftl::mmio::Normal>;
    // Domain1 Low Power Mode
    using CPU1_MODE = ftl::mmio::Field<2, 4, eCPU1_MODE, ftl::mmio::RO, ftl::mmio::Normal>;
    // Domain1 request enter Low Power Mode
    using CPU1_MODE_REQUEST = ftl::mmio::Field<1, 6, eCPU1_MODE_REQUEST, ftl::mmio::RO, ftl::mmio::Normal>;
    // Domain1 Low Power Mode task done
    using CPU1_MODE_DONE = ftl::mmio::Field<1, 7, eCPU1_MODE_DONE, ftl::mmio::RO, ftl::mmio::Normal>;
    // Domain2 Low Power Mode
    using CPU2_MODE = ftl::mmio::Field<2, 8, eCPU2_MODE, ftl::mmio::RO, ftl::mmio::Normal>;
    // Domain2 request enter Low Power Mode
    using CPU2_MODE_REQUEST = ftl::mmio::Field<1, 10, eCPU2_MODE_REQUEST, ftl::mmio::RO, ftl::mmio::Normal>;
    // Domain2 Low Power Mode task done
    using CPU2_MODE_DONE = ftl::mmio::Field<1, 11, eCPU2_MODE_DONE, ftl::mmio::RO, ftl::mmio::Normal>;
    // Domain3 Low Power Mode
    using CPU3_MODE = ftl::mmio::Field<2, 12, eCPU3_MODE, ftl::mmio::RO, ftl::mmio::Normal>;
    // Domain3 request enter Low Power Mode
    using CPU3_MODE_REQUEST = ftl::mmio::Field<1, 14, eCPU3_MODE_REQUEST, ftl::mmio::RO, ftl::mmio::Normal>;
    // Domain3 Low Power Mode task done
    using CPU3_MODE_DONE = ftl::mmio::Field<1, 15, eCPU3_MODE_DONE, ftl::mmio::RO, ftl::mmio::Normal>;
    // Next Setpoint to change to
    using TARGET_SETPOINT = ftl::mmio::Field<4, 16, std::uint8_t, ftl::mmio::RO, ftl::mmio::Normal>;
    // Current Setpoint
    using CURRENT_SETPOINT = ftl::mmio::Field<4, 20, std::uint8_t, ftl::mmio::RO, ftl::mmio::Normal>;
    // Clock gate turn off request from GPC Setpoint
    using SETPOINT_OFF_REQUEST = ftl::mmio::Field<1, 24, eSETPOINT_OFF_REQUEST, ftl::mmio::RO, ftl::mmio::Normal>;
    // Clock gate turn off finish from GPC Setpoint
    using SETPOINT_OFF_DONE = ftl::mmio::Field<1, 25, eSETPOINT_OFF_DONE, ftl::mmio::RO, ftl::mmio::Normal>;
    // Clock gate turn on request from GPC Setpoint
    using SETPOINT_ON_REQUEST = ftl::mmio::Field<1, 26, eSETPOINT_ON_REQUEST, ftl::mmio::RO, ftl::mmio::Normal>;
    // Clock gate turn on finish from GPC Setpoint
    using SETPOINT_ON_DONE = ftl::mmio::Field<1, 27, eSETPOINT_ON_DONE, ftl::mmio::RO, ftl::mmio::Normal>;
  };  // struct Lpcg94Status1Fields

