    // Non-secure access
    using TZ_NS = ftl::mmio::Field<1, 1, eTZ_NS, ftl::mmio::RW, ftl::mmio::Normal>;
    // lock truszone setting
    using LOCK_TZ = ftl::mmio::Field<1, 4, eLOCK_TZ, ftl::mmio::RW, ftl::mmio::Normal>;
    // Whitelist
