    // Depend level
    using LEVEL0 = ftl::mmio::Field<3, 16, eLEVEL0, ftl::mmio::RW, ftl::mmio::Normal>;
    // Depend level
    using LEVEL1 = ftl::mmio::Field<3, 20, eLEVEL1, ftl::mmio::RW, ftl::mmio::Normal>;
    // Depend level
    using LEVEL2 = ftl::mmio::Field<3, 24, eLEVEL2, ftl::mmio::RW, ftl::mmio::Normal>;
    // Depend level
    using LEVEL3 = ftl::mmio::Field<3, 28, eLEVEL3, ftl::mmio::RW, ftl::mmio::Normal>;
