    using TZ_USER = OscpllAuthenFields::TZ_USER;
    using TZ_NS = OscpllAuthenFields::TZ_NS;
    using LOCK_TZ = OscpllAuthenFields::LOCK_TZ;
    using WHITE_LIST = OscpllAuthenFields::WHITE_LIST;
